private var VenworksCanvasRegistryLoader:Loader = null;

private var VenworksCanvasRegistryBridge:MovieClip = null;

private var VenworksCanvasRegistryDisposed:Boolean = false;

private var VenworksCanvasHudOpacity:Number = 1;

public function getVenworksCanvasDataManager() : Object
{
   return BSUIDataManager;
}

public function getVenworksCanvasHudLayout() : Object
{
   var visibleRect:Object = Extensions.visibleRect;
   return {
      "visibleX":Number(visibleRect.x),
      "visibleY":Number(visibleRect.y),
      "visibleWidth":Number(visibleRect.width),
      "visibleHeight":Number(visibleRect.height),
      "safeX":Number(SafeX),
      "safeY":Number(SafeY),
      "ownerAppliesOpacity":true
   };
}

public function playVenworksCanvasSound(param1:String) : Boolean
{
   switch(param1)
   {
      case "VOC_Player_O2_Min":
      case "VOC_Player_CO2_Cleared":
      case "VOC_Player_CO2_Max":
      case "UIAfflictionPainWarningScreenOn":
      case "UIAfflictionPainWarningScreenOff":
      case "UIHazardRadiationWarningScreen":
      case "UIHazardThermalWarningScreen":
      case "UIHazardAirborneWarningScreen":
      case "UIHazardCorrosiveWarningScreen":
      case "UIHazardSuitSoakRestore_WarningScreen":
      case "UIHazardDamagePermanent":
      case "UIHazardRadiationWarningIcon":
      case "UIHazardThermalWarningIcon":
      case "UIHazardAirborneWarningIcon":
      case "UIHazardCorrosiveWarningIcon":
      case "UIHazardSuitSoakRestore_Icon":
         GlobalFunc.PlayMenuSound(param1);
         return true;
   }
   return false;
}

private function refreshVenworksCanvasLayout() : void
{
   if(!this.VenworksCanvasRegistryDisposed && this.VenworksCanvasRegistryBridge != null && "reapplyVanillaPlacements" in this.VenworksCanvasRegistryBridge)
   {
      try
      {
         this.VenworksCanvasRegistryBridge["reapplyVanillaPlacements"](this.getVenworksCanvasHudLayout());
      }
      catch(venworksCanvasLayoutError:*)
      {
      }
   }
}

private function startVenworksCanvasRegistry() : void
{
   if(this.VenworksCanvasRegistryLoader != null || this.VenworksCanvasRegistryDisposed)
   {
      return;
   }
   this.VenworksCanvasRegistryLoader = new Loader();
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.addEventListener(Event.INIT,this.onVenworksCanvasRegistryInit,false,0,true);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.addEventListener(Event.COMPLETE,this.onVenworksCanvasRegistryComplete,false,0,true);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.addEventListener(IOErrorEvent.IO_ERROR,this.onVenworksCanvasRegistryError,false,0,true);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.addEventListener(SecurityErrorEvent.SECURITY_ERROR,this.onVenworksCanvasRegistryError,false,0,true);
   addEventListener(Event.REMOVED_FROM_STAGE,this.onVenworksCanvasRegistryRemoved,false,0,true);
   try
   {
      this.VenworksCanvasRegistryLoader.load(new URLRequest("venworkscui.swf"));
   }
   catch(venworksCanvasLoadError:Error)
   {
      trace("VWCANVAS-PLAYER-AUX-LOAD | " + venworksCanvasLoadError.toString());
      this.disposeVenworksCanvasRegistry();
   }
}

private function onVenworksCanvasRegistryInit(param1:Event) : void
{
   if(this.VenworksCanvasRegistryDisposed || this.VenworksCanvasRegistryLoader == null)
   {
      return;
   }
   try
   {
      this.VenworksCanvasRegistryBridge = this.VenworksCanvasRegistryLoader.content as MovieClip;
      if(this.VenworksCanvasRegistryBridge == null || !("initialize" in this.VenworksCanvasRegistryBridge))
      {
         throw new Error("Canvas registry auxiliary does not expose initialize()");
      }
   }
   catch(venworksCanvasInitError:*)
   {
      this.disposeVenworksCanvasRegistry();
      trace("VWCANVAS-PLAYER-AUX-INIT | initialization failed");
   }
}

private function onVenworksCanvasRegistryComplete(param1:Event) : void
{
   var loadedContent:MovieClip = null;
   if(this.VenworksCanvasRegistryDisposed || this.VenworksCanvasRegistryLoader == null)
   {
      return;
   }
   this.removeVenworksCanvasRegistryListeners();
   try
   {
      loadedContent = this.VenworksCanvasRegistryLoader.content as MovieClip;
      if(loadedContent == null || this.VenworksCanvasRegistryBridge !== loadedContent)
      {
         throw new Error("initialized content was not retained");
      }
      if(this.VenworksCanvasRegistryBridge.parent !== this)
      {
         addChild(this.VenworksCanvasRegistryBridge);
      }
      this.VenworksCanvasRegistryBridge.alpha = this.VenworksCanvasHudOpacity;
      addEventListener(Event.ENTER_FRAME,this.onVenworksCanvasRegistryDeferredInitialize,false,0,true);
   }
   catch(venworksCanvasCompleteError:Error)
   {
      trace("VWCANVAS-PLAYER-AUX-COMPLETE | " + venworksCanvasCompleteError.toString());
      this.disposeVenworksCanvasRegistry();
   }
}

private function onVenworksCanvasRegistryDeferredInitialize(param1:Event) : void
{
   removeEventListener(Event.ENTER_FRAME,this.onVenworksCanvasRegistryDeferredInitialize);
   if(this.VenworksCanvasRegistryDisposed || this.VenworksCanvasRegistryBridge == null)
   {
      return;
   }
   try
   {
      if(this.VenworksCanvasRegistryBridge["initialize"](this,{"protocol":"VWCANVAS_HOST/1","hostKind":"player","displayMode":"__VWCANVAS_DISPLAY_MODE__","layout":this.getVenworksCanvasHudLayout()}) !== true)
      {
         throw new Error("Canvas registry auxiliary rejected host initialization");
      }
   }
   catch(venworksCanvasInitError:*)
   {
      this.disposeVenworksCanvasRegistry();
      trace("VWCANVAS-PLAYER-AUX-INIT | initialization failed");
   }
}

private function onVenworksCanvasRegistryError(param1:Event) : void
{
   trace("VWCANVAS-PLAYER-AUX-ERROR | " + param1.toString());
   this.disposeVenworksCanvasRegistry();
}

private function onVenworksCanvasRegistryRemoved(param1:Event) : void
{
   if(param1.target === this)
   {
      this.disposeVenworksCanvasRegistry();
   }
}

private function removeVenworksCanvasRegistryListeners() : void
{
   if(this.VenworksCanvasRegistryLoader == null)
   {
      return;
   }
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.removeEventListener(Event.INIT,this.onVenworksCanvasRegistryInit);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.removeEventListener(Event.COMPLETE,this.onVenworksCanvasRegistryComplete);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.removeEventListener(IOErrorEvent.IO_ERROR,this.onVenworksCanvasRegistryError);
   this.VenworksCanvasRegistryLoader.contentLoaderInfo.removeEventListener(SecurityErrorEvent.SECURITY_ERROR,this.onVenworksCanvasRegistryError);
}

private function disposeVenworksCanvasRegistry() : void
{
   if(this.VenworksCanvasRegistryDisposed)
   {
      return;
   }
   this.VenworksCanvasRegistryDisposed = true;
   removeEventListener(Event.ENTER_FRAME,this.onVenworksCanvasRegistryDeferredInitialize);
   removeEventListener(Event.REMOVED_FROM_STAGE,this.onVenworksCanvasRegistryRemoved);
   this.removeVenworksCanvasRegistryListeners();
   if(this.VenworksCanvasRegistryBridge != null && "dispose" in this.VenworksCanvasRegistryBridge)
   {
      try
      {
         this.VenworksCanvasRegistryBridge["dispose"]();
      }
      catch(venworksCanvasDisposeError:*)
      {
      }
   }
   if(this.VenworksCanvasRegistryBridge != null && this.VenworksCanvasRegistryBridge.parent === this)
   {
      removeChild(this.VenworksCanvasRegistryBridge);
   }
   this.VenworksCanvasRegistryBridge = null;
   if(this.VenworksCanvasRegistryLoader != null)
   {
      try
      {
         this.VenworksCanvasRegistryLoader.unload();
      }
      catch(venworksCanvasUnloadError:Error)
      {
      }
   }
   this.VenworksCanvasRegistryLoader = null;
}
